/**
 * Project freeze: while a project is archived, its issues and everything attached to them are read-only.
 *
 * Must call (do not reimplement): assertNotArchived
 */
import { assertNotArchived } from "@/lib/soft-delete";
import * as projectRepo from "@/server/repositories/project-repository";
import { requireFound } from "./_support";
import type { Issue } from "@/types/issue";

/**
 * Refuses a write to `issue`, or to a comment or attachment on it, when the
 * issue's project is archived. Callers run this after their permission and
 * own-archive checks, so those keep precedence, and before any side effect.
 */
export async function assertIssueWritable(issue: Issue): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(issue.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);
}

