import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let issue: Issue;
let commentId: string;
let attachmentId: string;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("freeze");
  resetOverdueTracking();
  issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title: "Frozen soon",
      dueAt: "2026-01-01T00:00:00.000Z",
    }),
  );
  const c = await commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body: "hello",
    mentionedUserIds: [],
  } as never);
  commentId = c.id;
  const a = await attachmentService.addAttachment(tenant.actors.owner, {
    orgId: tenant.org.id,
    issueId: issue.id,
    fileName: "a.txt",
    sizeBytes: 10,
    mimeType: "text/plain",
    storageKey: "k",
  } as never);
  attachmentId = a.id;
});

afterAll(() => cleanup());

describe("project freeze", () => {
  it("archiving without archiveIssues leaves issues live but frozen", async () => {
    await projectService.archiveProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    } as never);
    const live = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(live?.archivedAt).toBeNull();

    await expect(
      issueService.updateIssue(tenant.actors.owner, { orgId: tenant.org.id, issueId: issue.id, title: "x" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.changeIssueStatus(tenant.actors.owner, { orgId: tenant.org.id, issueId: issue.id, status: "done" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.assignIssue(tenant.actors.owner, { orgId: tenant.org.id, issueId: issue.id, assigneeId: null } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.archiveIssue(tenant.actors.owner, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, body: "nope", mentionedUserIds: [] } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      attachmentService.addAttachment(tenant.actors.owner, { orgId: tenant.org.id, issueId: issue.id, fileName: "b", sizeBytes: 1, mimeType: "x", storageKey: "k2" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      attachmentService.removeAttachment(tenant.actors.owner, { orgId: tenant.org.id, attachmentId } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    // reads still work
    expect((await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id)).issue.title).toBe("Frozen soon");
    expect(await issueService.getBoard(tenant.actors.member, tenant.org.id, tenant.project.id)).toBeDefined();
  });

  it("overdue sweep skips the frozen issue", async () => {
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => {
      seen.push(p.issueId);
    });
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off();
    expect(seen).not.toContain(issue.id);
  });

  it("restoring the project lifts the freeze", async () => {
    await projectService.restoreProject(tenant.actors.owner, tenant.org.id, tenant.project.id);
    const updated = await issueService.updateIssue(tenant.actors.owner, { orgId: tenant.org.id, issueId: issue.id, title: "Thawed" } as never);
    expect(updated.title).toBe("Thawed");

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => {
      seen.push(p.issueId);
    });
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off();
    expect(seen).toContain(issue.id);
  });
});

